css:
/* Drop the max-width on pages that show a diff */
body:has(#files) .container-xl,
body:has(#files) .container-lg,
body:has([data-testid="progressive-diffs-list"]) .container-xl,
body:has(.js-diff-progressive-container) .container-xl {
  max-width: none !important;
}

/* Long lines wrap instead of scrolling sideways */
.blob-code-inner,
[data-testid="diff-text-cell"] {
  white-space: pre-wrap !important;
  word-break: break-word;
}
